'use client'

import { useState } from 'react'
import type { EvalMatrixProps } from '../schemas'
import { clopperPearson } from '../verify/stats'
import { compareRuns } from './evalcompare'
import { after } from './theatre'
import { Count } from './motion'
import { Check, Cross } from './icons'
import { cx, pct } from './util'

/** Cases by runs, with the pass rate and exact interval per run and a paired comparison of any two runs. */
export function EvalMatrix({ title, cases, runs, className }: EvalMatrixProps & { className?: string }) {
  const [baseIdx, setBase] = useState(0)
  const [candIdx, setCand] = useState(Math.min(1, runs.length - 1))
  const [filter, setFilter] = useState<'all' | 'flipped' | 'regressed' | 'improved'>('all')
  const base = runs[baseIdx] ?? runs[0]!
  const cand = runs[candIdx] ?? runs[runs.length - 1]!

  const stats = runs.map((run) => {
    const passes = cases.filter((c) => run.results[c.id] === true).length
    return { label: run.label, passes, ...clopperPearson(passes, cases.length) }
  })

  const same = baseIdx === candIdx
  const cmp = compareRuns(cases, base, cand, same)
  const { regressed, improved, flips, p } = cmp
  const tone = { regression: 'bad', 'possible-drift': 'warn', improvement: 'good', 'possible-gain': 'good', mixed: undefined, 'no-change': 'good', 'same-run': undefined }[cmp.verdict] as 'bad' | 'warn' | 'good' | undefined
  const verdict = { tone, text: cmp.text }
  const shown = cases.filter((c) => filter === 'all' || (filter === 'flipped' ? flips.has(c.id) : flips.get(c.id) === filter))
  // How each run stands against the "before" run: the count of cases it lost and won.
  const against = runs.map((r) => (r === base ? null : compareRuns(cases, base, r)))

  return (
    <section role="group" className={cx('ol', className)} aria-label={title}>
      <h3 className="ol-title">{title}</h3>
      <div className="ol-scroll">
        <table className="ol-table">
          <thead>
            <tr>
              <th scope="col">Case</th>
              {runs.map((r, i) => <th scope="col" key={r.label}>{r.label}{against[i] && (against[i]!.regressed > 0 || against[i]!.improved > 0) && <div className="ol-sub" title={`Against ${base.label}: ${against[i]!.regressed} cases lost, ${against[i]!.improved} won`}>{against[i]!.regressed > 0 ? `▼${against[i]!.regressed}` : ''} {against[i]!.improved > 0 ? `▲${against[i]!.improved}` : ''}</div>}</th>)}
            </tr>
          </thead>
          <tbody>
            {shown.map((c, idx) => (
              <tr key={c.id} className="ol-in" style={after(idx)} data-flip={flips.get(c.id)}>
                <th scope="row">{c.label}</th>
                {runs.map((r) => (
                  <td key={r.label} data-pass={r.results[c.id] === true ? 'true' : 'false'}>
                    <span className="ol-cellmark" role="img" aria-label={r.results[c.id] === true ? 'pass' : 'fail'}>{r.results[c.id] === true ? <Check /> : <Cross />}</span>
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr>
              <th scope="row">Pass rate</th>
              {stats.map((s) => (
                <td key={s.label}>
                  <strong><Count value={(s.passes / cases.length) * 100} suffix="%" /></strong>
                  <div className="ol-sub">{pct(s.lower, 0)} to {pct(s.upper, 0)}</div>
                </td>
              ))}
            </tr>
          </tfoot>
        </table>
      </div>
      <div className="ol-chips" role="group" aria-label="Show cases" style={{ margin: '8px 0' }}>
        {([['all', 'All', cases.length], ['flipped', 'Changed', regressed + improved], ['regressed', 'Worse', regressed], ['improved', 'Better', improved]] as const).map(([id, label, n]) => (
          <button key={id} type="button" className="ol-chip" aria-pressed={filter === id} onClick={() => setFilter(id)}>{label} {n}</button>
        ))}
      </div>
      <div className="ol-compare-bar">
        <label>Before <select value={baseIdx} onChange={(e) => setBase(Number(e.target.value))}>{runs.map((r, i) => <option key={r.label} value={i}>{r.label}</option>)}</select></label>
        <label>After <select value={candIdx} onChange={(e) => setCand(Number(e.target.value))}>{runs.map((r, i) => <option key={r.label} value={i}>{r.label}</option>)}</select></label>
        <span className="ol-pill" data-tone={verdict.tone} role="status" title="Paired comparison on the same cases, exact McNemar test. Intervals are 95% exact.">{verdict.text}</span>{!same && <span className="ol-sub">p {p < 0.001 ? '< 0.001' : p.toFixed(3)}</span>}
      </div>
    </section>
  )
}

// Rules for comparing two evaluation runs on the same cases. The point of each: a drop is called a regression only
// when the flips are too lopsided to be chance, and when there are too few flips to ever tell, the page says so
// instead of colouring a number red.
import { mcnemarExact } from '../verify/stats'

export type EvalCase = { id: string; label: string }
export type EvalRun = { label: string; results: Record<string, boolean> }
export type Flip = 'regressed' | 'improved'
export type RunComparison = {
  regressed: number
  improved: number
  unchanged: number
  p: number
  /** The fewest flips, all one way, that could ever reach p under 0.05. Fewer than this can never be shown to be real. */
  flipsNeeded: number
  flips: Map<string, Flip>
  verdict: 'same-run' | 'no-change' | 'regression' | 'possible-drift' | 'improvement' | 'possible-gain' | 'mixed'
  text: string
}

/** Smallest n with 2 * 0.5^n under 0.05, which is when one-sided flips can first reach significance. */
export const flipsNeededFor = (alpha = 0.05) => Math.ceil(Math.log2(2 / alpha))

export function compareRuns(cases: EvalCase[], base: EvalRun, cand: EvalRun, same = false): RunComparison {
  const flips = new Map<string, Flip>()
  let regressed = 0
  let improved = 0
  for (const c of cases) {
    const a = base.results[c.id] === true
    const b = cand.results[c.id] === true
    if (a && !b) (regressed++, flips.set(c.id, 'regressed'))
    if (!a && b) (improved++, flips.set(c.id, 'improved'))
  }
  const p = mcnemarExact(regressed, improved)
  const unchanged = cases.length - regressed - improved
  const flipsNeeded = flipsNeededFor()
  const n = regressed + improved
  const counts = `${regressed} worse, ${improved} better`
  let verdict: RunComparison['verdict']
  let text: string
  if (same) { verdict = 'same-run'; text = 'Pick two different runs to compare.' }
  else if (n === 0) { verdict = 'no-change'; text = 'No case changed.' }
  else if (regressed > improved) {
    if (p < 0.05) { verdict = 'regression'; text = `Regression: ${counts}. Too lopsided to be chance (p ${p < 0.001 ? '< 0.001' : '= ' + p.toFixed(3)}).` }
    else { verdict = 'possible-drift'; text = `Possible drift: ${counts}. This could be chance (p = ${p.toFixed(2)}).${n < flipsNeeded ? ` With ${n} ${n === 1 ? 'case' : 'cases'} flipped it cannot be shown either way: it takes at least ${flipsNeeded}, all one way.` : ''}` }
  } else if (improved > regressed) {
    if (p < 0.05) { verdict = 'improvement'; text = `Improvement: ${counts}. Too lopsided to be chance (p ${p < 0.001 ? '< 0.001' : '= ' + p.toFixed(3)}).` }
    else { verdict = 'possible-gain'; text = `Possible gain: ${counts}. This could be chance (p = ${p.toFixed(2)}).${n < flipsNeeded ? ` With ${n} ${n === 1 ? 'case' : 'cases'} flipped it cannot be shown either way: it takes at least ${flipsNeeded}, all one way.` : ''}` }
  } else { verdict = 'mixed'; text = `${counts}. The same number moved each way, so nothing net changed.` }
  return { regressed, improved, unchanged, p, flipsNeeded, flips, verdict, text }
}
